<?php
require __DIR__.'/ui.php';role(['admin','gerente','vendedor']);$p=db();$days=max(30,(int)setting('inactive_days','90'));$inactive=$p->query("SELECT c.*,MAX(o.created_at) last_order FROM customers c LEFT JOIN orders o ON o.customer_id=c.id GROUP BY c.id HAVING last_order IS NULL OR date(last_order)<=date('now','-$days days') ORDER BY last_order")->fetchAll();$quotes=$p->query("SELECT q.*,c.name customer,c.whatsapp FROM quotes q LEFT JOIN customers c ON c.id=q.customer_id WHERE q.status='Em aberto' AND date(q.created_at)<=date('now','-2 days') ORDER BY q.created_at")->fetchAll();page_head('Recuperação de vendas');?>
<div class="grid g2"><div class="card"><h2>Clientes inativos (<?=$days?>+ dias)</h2><div class="table"><table><tr><th>Cliente</th><th>WhatsApp</th><th>Último pedido</th></tr><?php foreach($inactive as $x):?><tr><td><?=e($x['name'])?></td><td><?=e($x['whatsapp'])?></td><td><?=e($x['last_order']?:'Nunca comprou')?></td></tr><?php endforeach;?></table></div></div><div class="card"><h2>Orçamentos parados</h2><div class="table"><table><tr><th>Orçamento</th><th>Cliente</th><th>WhatsApp</th><th>Valor</th></tr><?php foreach($quotes as $x):?><tr><td><?=e($x['number'])?></td><td><?=e($x['customer'])?></td><td><?=e($x['whatsapp'])?></td><td><?=money($x['amount'])?></td></tr><?php endforeach;?></table></div></div></div><?php page_foot();?>